fileGuard._verifyRequest = function (requestDetails) {

    const redirectUrl = chrome.runtime.getURL(Address.ROOT_PATH);

    // [PORT VIVALDI] Permitir los subrecursos que el navegador resuelve a partir de un
    // recurso servido por la extensión: fuentes, imágenes y medios referenciados con
    // rutas relativas (p. ej. url(../webfonts/fa-solid-900.woff2) dentro de un CSS de
    // Font Awesome, o los assets internos de TinyMCE). El navegador construye esas URLs
    // sin secreto y con initiator de la página o del CSS, así que por aquí pasan también
    // las peticiones iniciadas por la propia extensión. El secreto sigue siendo
    // obligatorio para scripts, hojas de estilo, frames y XHR: lo que permite leer el
    // contenido de un recurso.
    const esSubrecurso = ['font', 'image', 'media'].indexOf(requestDetails.type) > -1;
    const esDeLaExtension = requestDetails.initiator &&
        requestDetails.initiator.indexOf(fileGuard.origin) === 0;

    if (esSubrecurso || esDeLaExtension) {
        fileGuard._seen.push({
            url: requestDetails.url.replace(/^chrome-extension:\/\/[^/]+/, 'chrome-extension://<id>'),
            type: requestDetails.type,
            initiator: requestDetails.initiator
        });
        if (fileGuard._seen.length > 20) {
            fileGuard._seen.shift();
        }
        return;
    }

    // [PORT VIVALDI] Se compara por el valor del secreto ("=<hex>") en lugar del texto
    // completo "?=...", para aceptar también las URLs firmadas con "&_=".
    if (!requestDetails.url.endsWith(`=${fileGuard.secretValue}`)) {
        return {redirectUrl};
    }
};
